#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,k,m;
    while(cin>>n>>k>>m){
        vector<vector<long long>> dp(k+1, vector<long long>(n+1,0));
        dp[0][0]=1;
        for(int i=1;i<=k;i++)
            for(int j=0;j<=n;j++)
                for(int w=1;w<=m && w<=j;w++)
                    dp[i][j]+=dp[i-1][j-w];
        cout << dp[k][n] << "\n";
    }
}

